INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (1, 'English', 'Under the 1987 Constitution, sovereignty resides in the people and all government authority emanates from them. This principle is primarily found in:', '["Article II (Declaration of Principles and State Policies)","Article III (Bill of Rights)","Article VI (Legislative Department)","Article VII (Executive Department)"]'::jsonb, 0, 'Article II, Section 1 affirms that the Philippines is a democratic and republican State; sovereignty resides in the people.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (1, 'English', 'The power of judicial review allows the Supreme Court to:', '["Enact statutes when Congress fails to act","Determine whether a law or act is unconstitutional","Appoint Cabinet secretaries","Dissolve local government units unilaterally"]'::jsonb, 1, 'Judicial review is the authority of courts to invalidate governmental acts that conflict with the Constitution.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (1, 'English', 'Which body has the exclusive power to initiate impeachment cases against impeachable officers?', '["The Senate","The House of Representatives","The Supreme Court","The Ombudsman"]'::jsonb, 1, 'The House of Representatives has the exclusive power to initiate impeachment; the Senate tries impeachment cases.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (1, 'English', 'Members of the House of Representatives are elected for a term of:', '["Three years","Four years","Five years","Six years"]'::jsonb, 0, 'Article VI provides a three-year term for members of the House of Representatives.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (1, 'English', 'The Commission on Elections (COMELEC) is a:', '["Regular executive department under the DILG","Constitutional Commission under Article IX","Ad hoc body created only during election years","Committee of Congress"]'::jsonb, 1, 'COMELEC is one of the three independent Constitutional Commissions under Article IX.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (1, 'English', 'Natural-born citizens of the Philippines are those:', '["Who were naturalized by Congress only","Who are citizens from birth without having to perform any act to acquire or perfect citizenship","Who resided in the Philippines for ten continuous years","Who hold dual citizenship exclusively"]'::jsonb, 1, 'Article IV defines natural-born citizens as those who are citizens from birth without needing any act to acquire or perfect citizenship.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (1, 'English', 'The Writ of Amparo is primarily intended to protect:', '["Property rights in land disputes","The right to life, liberty, and security against extralegal threats","Corporate franchise renewals","Customs valuation disputes"]'::jsonb, 1, 'The Writ of Amparo is a remedy to protect persons whose right to life, liberty, and security is violated or threatened.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (1, 'English', 'Local government units enjoy local autonomy subject to:', '["Complete independence from national laws","Supervision by the President and applicable laws","Approval of barangay assemblies only","Exclusive control by the judiciary"]'::jsonb, 1, 'LGUs enjoy local autonomy but remain under the general supervision of the President and must follow national laws.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (1, 'English', 'The party-list system is designed primarily to:', '["Replace district representation entirely","Give marginalized and underrepresented sectors a voice in Congress","Elect the President by popular vote only","Appoint justices of the Supreme Court"]'::jsonb, 1, 'The party-list system aims to enable marginalized and underrepresented sectors to obtain seats in the House.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (1, 'English', 'Which of the following is NOT a Constitutional Commission?', '["Civil Service Commission","Commission on Audit","Commission on Human Rights","Commission on Elections"]'::jsonb, 2, 'CHR is an independent office created by the Constitution but is not one of the three Constitutional Commissions (CSC, COMELEC, COA).', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (2, 'English', 'Under R.A. 6713, public officials must always put which interest above personal interest?', '["Party interest","Public interest","Family business interest","Agency overtime interest only"]'::jsonb, 1, 'R.A. 6713 emphasizes that public interest must be upheld over personal interest.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (2, 'English', 'A Statement of Assets, Liabilities and Net Worth (SALN) must generally be filed:', '["Only when promoted","Upon assumption of office, annually, and upon separation","Every ten years","Only if salary exceeds a fixed threshold"]'::jsonb, 1, 'SALN filing is required upon assumption, every year thereafter, and upon separation from service.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (2, 'English', 'Which act is generally prohibited for public officials under the Code of Conduct?', '["Attending official training","Accepting gifts in connection with official duties","Reporting anomalies to proper authorities","Consulting stakeholders in policymaking"]'::jsonb, 1, 'Soliciting or accepting gifts related to official duties is among the prohibited acts under R.A. 6713.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (2, 'English', 'Transparency of public transactions under ethical standards typically requires:', '["Keeping all procurement secret until after award forever","Making information accessible as required by law and policy","Publishing only favorable news","Avoiding written records"]'::jsonb, 1, 'Ethical standards promote transparency and accessibility of public information consistent with law.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (2, 'English', 'Divestment under conflict-of-interest rules generally means:', '["Transferring conflicting financial interests within a required period","Resigning from all government posts immediately","Hiding assets from the SALN","Donating salary to charity"]'::jsonb, 0, 'Divestment refers to disposing of conflicting financial interests within the period required by law.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (2, 'English', 'Simple living as a norm for public officials under R.A. 6713 means officials should:', '["Live beyond their means to inspire confidence","Lead modest lives appropriate to their positions and income","Avoid any community involvement","Refuse all lawful compensation"]'::jsonb, 1, 'The Code encourages simple and modest living commensurate with position and lawful income.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (2, 'English', 'Which is an example of a conflict of interest?', '["An official deciding a bid where a close relative owns a bidder","An official attending a public hearing","An official filing a leave form","An official reading the Official Gazette"]'::jsonb, 0, 'Participating in a decision that affects a relative''s business interest is a classic conflict of interest.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (2, 'English', 'Whistleblowing about graft, when done through proper channels, is generally:', '["A prohibited act under R.A. 6713","Consistent with the duty to uphold public interest","Grounds for automatic dismissal","Allowed only for Cabinet members"]'::jsonb, 1, 'Reporting wrongdoing through lawful channels aligns with public interest and ethical duties.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (3, 'English', 'The principle of non-discrimination in human rights means rights apply:', '["Only to citizens with college degrees","To all persons without unjust distinction","Only during peacetime","Only to government employees"]'::jsonb, 1, 'Human rights are universal and must be enjoyed without unjust discrimination.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (3, 'English', 'Habeas corpus primarily protects against:', '["Unlawful detention","Unpaid taxes","Zoning violations","Trademark infringement"]'::jsonb, 0, 'Habeas corpus is a remedy against unlawful restraint of liberty.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (3, 'English', 'The Commission on Human Rights (CHR) is empowered to:', '["Convict criminal offenders in regular courts","Investigate human rights violations and monitor compliance","Enact criminal codes","Replace the Department of Justice"]'::jsonb, 1, 'CHR investigates human rights violations and monitors government observance of human rights; it does not try and convict as a regular court.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (3, 'English', 'Children''s rights under Philippine policy emphasize:', '["Forced labor as character building","Protection, education, and best interests of the child","Political campaigning before age 10","Exemption from all parental guidance"]'::jsonb, 1, 'Philippine policy prioritizes the best interests of the child, including protection and education.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (3, 'English', 'Freedom of expression may be limited when:', '["The government dislikes criticism of any kind","Speech creates a clear and present danger of substantive evil as allowed by law","A private citizen asks politely","An election is more than one year away"]'::jsonb, 1, 'Constitutional freedoms may be restricted under lawful standards such as clear and present danger, not mere dislike of criticism.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (3, 'English', 'Peace education in communities often focuses on:', '["Glorifying violence","Conflict resolution, respect for rights, and dialogue","Eliminating all elections","Banning all civic organizations"]'::jsonb, 1, 'Peace education promotes nonviolent conflict resolution, human rights, and constructive dialogue.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (3, 'English', 'Indigenous peoples'' rights in the Philippines are principally framed by:', '["R.A. 8371 (IPRA)","The Clean Air Act alone","The Negotiable Instruments Law","The Tariff and Customs Code only"]'::jsonb, 0, 'R.A. 8371, the Indigenous Peoples'' Rights Act (IPRA), is the principal statute on IP rights.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (3, 'English', 'Extrajudicial killing, if proven, violates primarily the right to:', '["Travel abroad","Life","Form corporations","Inherit property only"]'::jsonb, 1, 'Arbitrary deprivation of life violates the fundamental right to life.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (4, 'English', 'R.A. 9003 primarily deals with:', '["Clean air standards only","Ecological solid waste management","Income taxation","Civil service eligibility"]'::jsonb, 1, 'R.A. 9003 is the Ecological Solid Waste Management Act.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (4, 'English', 'An Environmental Impact Statement (EIS) system is important because it:', '["Removes all project regulation","Assesses potential environmental effects before major projects proceed","Replaces building permits entirely","Applies only to residential backyard gardens"]'::jsonb, 1, 'The EIS system evaluates significant environmental impacts of covered projects before implementation.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (4, 'English', 'The precautionary principle in environmental policy suggests that:', '["Action to prevent harm may be taken even if scientific certainty is incomplete","Pollution should continue until absolute proof of harm","Only foreign companies need permits","Trees may be cut without assessment always"]'::jsonb, 0, 'The precautionary approach supports preventive measures despite incomplete scientific certainty of harm.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (4, 'English', 'Climate change adaptation in local governance commonly includes:', '["Ignoring flood maps","Disaster risk reduction planning and resilient infrastructure","Banning all weather forecasts","Removing drainage systems"]'::jsonb, 1, 'Adaptation includes DRRM planning, resilient design, and risk-informed land use.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (4, 'English', 'Illegal logging primarily threatens:', '["Forest ecosystems and biodiversity","Only coastal mangroves in other countries","Stock market indexes exclusively","Postal delivery schedules"]'::jsonb, 0, 'Illegal logging depletes forests and harms biodiversity and watershed functions.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (4, 'English', 'Segregation at source in solid waste management means:', '["Mixing all waste before collection","Separating recyclables, biodegradables, and residuals at the household or establishment","Burning plastics in open pits only","Dumping waste in rivers"]'::jsonb, 1, 'Segregation at source separates waste types where they are generated to enable proper processing.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (4, 'English', 'Protected areas under the NIPAS framework are intended to:', '["Maximize commercial mining without review","Conserve biodiversity and ecological processes","Convert all forests to subdivisions automatically","Eliminate tourism forever"]'::jsonb, 1, 'NIPAS aims to protect and maintain biodiversity and vital ecological processes in protected areas.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (4, 'English', 'Which agency is primarily associated with environmental management and natural resources at the national level?', '["Department of Environment and Natural Resources (DENR)","Bureau of Internal Revenue","Philippine Statistics Authority alone","Land Transportation Office alone"]'::jsonb, 0, 'DENR is the primary national agency for environment and natural resources management.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (5, 'English', 'The word PRUDENT most nearly means:', '["Reckless","Wise and careful","Noisy","Obsolete"]'::jsonb, 1, 'Prudent means acting with or showing care and thought for the future.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (5, 'English', 'An antonym of SCARCE is:', '["Rare","Abundant","Limited","Sparse"]'::jsonb, 1, 'Scarce means in short supply; abundant is the opposite.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (5, 'English', 'CANDID most nearly means:', '["Deceitful","Frank and honest","Ambiguous","Hostile"]'::jsonb, 1, 'Candid means truthful and straightforward.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (5, 'English', 'The word MITIGATE is closest in meaning to:', '["Intensify","Lessen or make less severe","Ignore completely","Celebrate"]'::jsonb, 1, 'To mitigate is to make milder or less severe.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (5, 'English', 'A synonym of IMPARTIAL is:', '["Biased","Fair and unbiased","Emotional","Secretive"]'::jsonb, 1, 'Impartial means treating all rivals or disputants equally; fair.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (5, 'English', 'The word VERBOSE describes writing that is:', '["Concise","Wordy","Silent","Illustrated only"]'::jsonb, 1, 'Verbose means using more words than needed.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (5, 'English', 'RESILIENT most nearly means:', '["Fragile","Able to recover quickly","Permanent","Indifferent"]'::jsonb, 1, 'Resilient means able to withstand or recover quickly from difficulties.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (5, 'English', 'An antonym of TRANSPARENT (in governance contexts) is:', '["Open","Opaque or secretive","Clear","Accountable"]'::jsonb, 1, 'Transparent means open/clear; opaque or secretive is opposite in this sense.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (5, 'English', 'CREDIBLE evidence is evidence that is:', '["Unbelievable","Believable and trustworthy","Illegal","Anonymous only"]'::jsonb, 1, 'Credible means able to be believed; convincing.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (6, 'English', 'Despite the limited budget, the agency remained _____ and completed the project on time.', '["profligate","resourceful","apathetic","negligent"]'::jsonb, 1, 'Resourceful fits: they found ways despite constraints.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (6, 'English', 'The auditor''s report was so _____ that even non-experts understood the findings.', '["obscure","lucid","convoluted","ambiguous"]'::jsonb, 1, 'Lucid means clear and easy to understand.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (6, 'English', 'Public servants are expected to act with _____ even when no one is watching.', '["integrity","indifference","partiality","hostility"]'::jsonb, 0, 'Integrity is honesty and strong moral principles.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (6, 'English', 'The committee postponed the hearing _____ additional documents could be reviewed.', '["unless","so that","although","despite"]'::jsonb, 1, '"So that" expresses purpose for the postponement.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (6, 'English', 'Her explanation failed to _____ the panel''s doubts about the data.', '["aggravate","allay","amplify","announce"]'::jsonb, 1, 'Allay means to diminish or put to rest (fears/doubts).', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (6, 'English', 'The policy was revised _____ feedback from frontline employees.', '["in spite of","in light of","instead of ignoring","regardless without"]'::jsonb, 1, '"In light of" means considering / because of.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (6, 'English', 'Efficient filing systems help clerks retrieve records with minimal _____.', '["delay","clarity","accuracy","legibility"]'::jsonb, 0, 'Good systems reduce delay in retrieval.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (6, 'English', 'The mayor emphasized that disaster drills are not optional but _____.', '["discretionary","mandatory","decorative","theoretical only"]'::jsonb, 1, 'Mandatory means required by rules or law.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (7, 'English', 'Which sentence contains an error?', '["The data suggest a clear trend.","Between you and I, the plan needs work.","Everybody is ready for the briefing.","Fewer errors appeared in the revised draft."]'::jsonb, 1, 'Correct pronoun: "Between you and me" (object of preposition).', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (7, 'English', 'Choose the sentence with incorrect subject-verb agreement.', '["Mathematics is challenging for many students.","Each of the reports need further review.","There are several options on the table.","News is broadcast daily."]'::jsonb, 1, '"Each" is singular; use "needs," not "need."', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (7, 'English', 'Which sentence has a pronoun error?', '["Everyone should bring his or her ID.","The team submitted their joint proposal.","If a person works hard, they will succeed eventually. (informal)","Me and him will attend the orientation."]'::jsonb, 3, 'Subject pronouns needed: "He and I will attend..."', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (7, 'English', 'Identify the erroneous sentence.', '["She speaks both English and Filipino fluently.","He don''t know the deadline.","They have already left the office.","We were informed yesterday."]'::jsonb, 1, 'Third-person singular: "He doesn''t know..."', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (7, 'English', 'Which sentence uses a wrong comparative form?', '["This form is simpler than the old one.","She is the most qualified among the three.","This approach is more better than the last.","Our office is farther from the hall than yours."]'::jsonb, 2, '"More better" is a double comparative; use "better."', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (7, 'English', 'Choose the sentence with a misplaced modifier problem.', '["Walking to the office, Ana reviewed her notes.","Covered in dust, the clerk filed the old folders carefully.","Running late, the report was submitted by the staff.","After the meeting, they clarified the agenda."]'::jsonb, 2, 'The report was not running late; the modifier dangles. Better: "Running late, the staff submitted the report."', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (8, 'English', 'A compound sentence typically contains:', '["One independent clause only","Two or more independent clauses joined appropriately","Only dependent clauses","A title without a verb"]'::jsonb, 1, 'Compound sentences join independent clauses (e.g., with coordinating conjunctions).', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (8, 'English', 'Which is a complex sentence?', '["The clerk filed the papers.","The clerk filed the papers, and the manager signed them.","Although the clerk filed the papers, the manager requested revisions.","File. Sign. Archive."]'::jsonb, 2, 'A complex sentence has an independent clause plus at least one dependent clause ("Although...").', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (8, 'English', 'Parallel structure is correctly used in:', '["She likes hiking, to swim, and biking.","She likes hiking, swimming, and biking.","She likes hike, swimming, and to bike.","She likes hiking, swim, and biked."]'::jsonb, 1, 'Parallel gerunds: hiking, swimming, and biking.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (8, 'English', 'A run-on sentence is best corrected by:', '["Adding more unrelated clauses without punctuation","Using proper punctuation or conjunctions to separate independent clauses","Removing all verbs","Writing only fragments"]'::jsonb, 1, 'Run-ons need correct separation/joining of independent clauses.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (8, 'English', 'Which option is a sentence fragment?', '["The training starts at nine.","Because the documents were incomplete.","Please submit your forms today.","Who will lead the briefing?"]'::jsonb, 1, '"Because..." alone is a dependent clause fragment.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (8, 'English', 'Active voice is illustrated by:', '["The report was written by the analyst.","The analyst wrote the report.","The report has been being written.","Writing of the report was done."]'::jsonb, 1, 'Active: subject performs the action — "The analyst wrote..."', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (9, 'English', 'The topic sentence of a paragraph usually:', '["Hides the main idea until the last footnote","States the main idea the paragraph develops","Lists only unrelated examples","Must be a question always"]'::jsonb, 1, 'A topic sentence presents the paragraph''s controlling idea.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (9, 'English', 'Coherence in a paragraph is improved by:', '["Random jumps between unrelated topics","Logical order and clear transitions","Repeating the same sentence ten times","Omitting all examples"]'::jsonb, 1, 'Coherence comes from logical sequencing and transitional devices.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (9, 'English', 'Which order best fits a process paragraph?', '["Random steps","Chronological or sequential steps","Alphabetical only by author surname","Reverse of conclusion first without setup always"]'::jsonb, 1, 'Process writing typically follows chronological/sequential order.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (9, 'English', 'A concluding sentence often:', '["Introduces an entirely new topic without link","Restates or wraps up the paragraph''s idea","Deletes the topic sentence retroactively","Must apologize for the content"]'::jsonb, 1, 'Conclusions reinforce or close the paragraph''s point.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (9, 'English', 'Unity in a paragraph means:', '["All sentences support one main idea","Each sentence discusses a different subject","No examples are allowed","Only questions are used"]'::jsonb, 0, 'Unity requires relevance of all sentences to one controlling idea.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (9, 'English', 'Transitional words like "however" and "therefore" help show:', '["Font size","Logical relationships between ideas","Page margins","Speaker volume"]'::jsonb, 1, 'Transitions signal contrast, cause-effect, addition, etc.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (10, 'English', 'Passage: "Open data portals allow citizens to examine government spending." The author''s main point is that open data:', '["Prevents all corruption automatically","Helps citizens scrutinize how public funds are used","Replaces the need for elections","Applies only to private banks"]'::jsonb, 1, 'The sentence links open data to citizen examination of spending.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (10, 'English', 'Passage: "Training without follow-up coaching yields short-lived gains." An inference is that:', '["Coaching after training can help sustain improvements","Training is useless in all cases","Coaching replaces all training","Gains never occur"]'::jsonb, 0, 'If lack of follow-up shortens gains, coaching after training likely helps sustain them.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (10, 'English', 'Passage: "Flood-prone barangays updated their evacuation maps yearly." This suggests the maps are:', '["Never used","Treated as living documents needing periodic revision","Illegal","Only decorative"]'::jsonb, 1, 'Yearly updates imply maps are maintained and revised over time.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (10, 'English', 'Passage: "Merit-based hiring strengthens public trust in bureaucracy." Which restatement is best?', '["Hiring by connections always builds trust","Selecting officials based on qualifications can increase confidence in government","Bureaucracy should ignore merit","Trust is unrelated to hiring"]'::jsonb, 1, 'Merit-based selection is linked to stronger public trust.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (10, 'English', 'Passage: "Digital literacy gaps widen inequality in accessing e-government services." The problem highlighted is:', '["Printer ink costs only","Unequal ability to use digital tools limiting access to services","Too many service centers downtown","Excess paper forms exclusively"]'::jsonb, 1, 'Digital literacy gaps create unequal access to online government services.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (10, 'English', 'Passage: "Evidence-based policy relies on data rather than anecdotes alone." The author contrasts:', '["Data-informed decisions vs. story-only decisions","Anecdotes vs. poetry","Policy vs. law dictionaries","Servers vs. desktops"]'::jsonb, 0, 'The contrast is between data/evidence and anecdote-only approaches.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (10, 'English', 'If a passage states a rule and an exception, a careful reader should:', '["Ignore the exception","Note both the general rule and the stated exception","Assume no exceptions ever exist","Skip to the title only"]'::jsonb, 1, 'Accurate comprehension includes both the rule and any stated exceptions.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (10, 'English', 'Passage: "Community feedback shortened the permit process by two days." A reasonable conclusion is that:', '["Feedback had no effect","Stakeholder input contributed to process improvement","Permits were abolished","Two days were added"]'::jsonb, 1, 'The stated result links feedback to a shorter process.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (11, 'English', 'Judge is to Court as Physician is to:', '["Hospital","Medicine bottle","Ambulance siren","Prescription pad only"]'::jsonb, 0, 'A judge works in a court; a physician commonly works in a hospital.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (11, 'English', 'Author is to Book as Composer is to:', '["Concert hall","Symphony","Instrument case","Audience"]'::jsonb, 1, 'An author produces a book; a composer produces a musical work such as a symphony.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (11, 'English', 'Vaccine is to Prevention as Antibiotic is to:', '["Diagnosis only","Treatment of bacterial infection","Surgery theater","X-ray film"]'::jsonb, 1, 'Vaccines prevent disease; antibiotics treat bacterial infections.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (11, 'English', 'Blueprint is to Building as Agenda is to:', '["Meeting","Calendar app icon","Coffee break","Name tag"]'::jsonb, 0, 'A blueprint guides construction; an agenda guides a meeting.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (11, 'English', 'Archipelago is to Islands as Constellation is to:', '["Planets only","Stars","Oceans","Comets exclusively"]'::jsonb, 1, 'An archipelago is a group of islands; a constellation is a group of stars.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (11, 'English', 'Librarian is to Catalog as Accountant is to:', '["Ledger","Bookshelf","Barcode","Reading lamp"]'::jsonb, 0, 'Librarians organize via catalogs; accountants organize via ledgers.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (11, 'English', 'Drought is to Scarcity as Flood is to:', '["Abundance of water / excess","Desertification only","Evaporation","Irrigation canal"]'::jsonb, 0, 'Drought relates to scarcity of water; flood relates to excess water.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (11, 'English', 'Hypothesis is to Experiment as Verdict is to:', '["Trial","Lawyer briefcase","Courtroom sketch","Bail bond"]'::jsonb, 0, 'A hypothesis is tested by experiment; a verdict results from a trial.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (11, 'English', 'Filter is to Purification as Audit is to:', '["Verification / accountability check","Celebration","Decoration","Translation only"]'::jsonb, 0, 'Filtering purifies; auditing verifies accountability.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (11, 'English', 'Scout is to Reconnaissance as Spy satellite is to:', '["Surveillance","Agriculture subsidy","Postal sorting","Museum tour"]'::jsonb, 0, 'Scouts perform reconnaissance; spy satellites perform surveillance.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (12, 'English', 'If all A are B, and some B are C, which must be true?', '["All A are C","Some A may or may not be C; not determined from given alone","No A are C","All C are A"]'::jsonb, 1, 'From all A are B and some B are C, the relation of A to C is not forced.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (12, 'English', 'Statement: If it rains, the event is moved indoors. It did not rain. Therefore:', '["The event must have been outdoors","We cannot conclude the event location from this alone","The event was canceled","It must have flooded"]'::jsonb, 1, 'Denying the antecedent does not validly deny the consequent.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (12, 'English', 'Which pair is the odd one out by pattern: 2A, 4C, 6E, 9G?', '["2A","4C","6E","9G"]'::jsonb, 3, 'Numbers increase by +2 and letters skip one; 9 breaks the +2 number pattern (should be 8G).', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (12, 'English', 'Complete the series: AZ, BY, CX, _____', '["DW","EV","DU","CW"]'::jsonb, 0, 'First letters A,B,C,D; second letters Z,Y,X,W yielding DW.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (12, 'English', 'If triangle means addition and circle means subtraction, then 8 triangle 3 circle 2 equals:', '["9","13","3","6"]'::jsonb, 0, '8+3-2 = 9.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (12, 'English', 'All managers are employees. Some employees are engineers. Which is valid if at least one manager exists?', '["All managers are engineers","Some managers are definitely engineers","Some employees are managers","No employees are managers"]'::jsonb, 2, 'Each manager is an employee, so some employees are managers.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (12, 'English', 'Find the next in pattern: circle, square, circle, square, circle, _____', '["Square","Triangle","Pentagon","Line"]'::jsonb, 0, 'Alternating circle/square continues with square.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (12, 'English', 'Which conclusion follows? Only citizens may vote. Alex voted.', '["Alex is a citizen","Alex is a government employee","Alex is over 60","Alex owns land"]'::jsonb, 0, 'If only citizens may vote and Alex voted, Alex must be a citizen.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (12, 'English', 'Code: FIRE = 1234, LIFE = 5124. Then LIE could be:', '["514","152","512","124"]'::jsonb, 0, 'L=5, I=1, E=4 so LIE = 514.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (12, 'English', 'If the first two are true, is the third necessarily true? (1) All roses are flowers. (2) Some flowers fade quickly. (3) Some roses fade quickly.', '["Yes, necessarily","No, not necessarily","Yes only if all flowers are roses","Cannot read"]'::jsonb, 1, 'Some flowers fading does not force roses to be among those that fade.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (13, 'English', 'Argument: We should hire more clerks because queues are long. An unstated assumption is that:', '["Long queues are unrelated to staffing","Additional clerks would help reduce queue length","Queues are preferred by clients","Hiring is free"]'::jsonb, 1, 'The recommendation assumes more clerks would address the queue problem.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (13, 'English', 'All eligible applicants submitted forms on time. Ben did not submit on time. Conclusion:', '["Ben is eligible","Ben is not an eligible applicant under the given rule","Ben will be hired","Ben submitted early"]'::jsonb, 1, 'By contraposition, not on time implies not among those eligible applicants described.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (13, 'English', 'Which is a value judgment rather than a factual claim?', '["The office processed 120 applications yesterday","Transparency is more important than speed in this case","The building has five floors","The meeting starts at 9:00 a.m."]'::jsonb, 1, 'Calling one value more important is a normative judgment.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (13, 'English', 'Survey: 70% of respondents support flex-time. Strongest caution?', '["Sample may not represent the whole workforce","Percentages are never useful","Flex-time is illegal always","Surveys cannot ask about time"]'::jsonb, 0, 'Representativeness of the sample limits generalization.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (13, 'English', 'If whenever inventory is low, orders are placed, and orders were not placed, then:', '["Inventory must be low","Inventory is not low","Suppliers failed","Prices rose"]'::jsonb, 1, 'Modus tollens: not orders implies not low inventory.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (13, 'English', 'Claim: Program X caused the score increase. Weakest support would be:', '["Randomized controlled comparison","Anecdote from one participant only","Pre-post study with controls","Replication across sites"]'::jsonb, 1, 'A single anecdote is weak causal evidence.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (13, 'English', 'Which is a necessary assumption for Install CCTV to reduce theft?', '["Theft is partly deterred or detectable via CCTV","CCTV entertains visitors","Theft only happens online","Cameras replace locks always"]'::jsonb, 0, 'The policy assumes CCTV helps deter or detect theft.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (13, 'English', 'Premises: Either the file is in Cabinet A or Cabinet B. It is not in Cabinet A. Conclusion:', '["It is in Cabinet B","It is lost forever","It is in both","Cabinets are empty"]'::jsonb, 0, 'Disjunctive syllogism yields Cabinet B.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (13, 'English', 'An argument attacks the speaker character instead of the claim. This fallacy is:', '["Ad hominem","Valid deduction","Statistical sampling","Analogy"]'::jsonb, 0, 'Ad hominem targets the person rather than the argument.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (13, 'English', 'After the new pavement, accidents fell; therefore pavement caused the drop. The flaw may be:', '["Ignoring other concurrent causes","Using too much data","Preferring experiments always illegally","Measuring accidents"]'::jsonb, 0, 'Post hoc or omitted variable issues may explain the drop.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (14, 'English', 'A chart shows Office A: 40 permits, Office B: 60 permits. Office B share of the combined total is:', '["40%","50%","60%","66%"]'::jsonb, 2, '60/(40+60)=60%.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (14, 'English', 'Scores: 70, 80, 90. The mean is:', '["70","80","90","240"]'::jsonb, 1, '(70+80+90)/3 = 80.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (14, 'English', 'If a pie chart shows 25% of 200 complaints are about delays, the number about delays is:', '["25","50","75","100"]'::jsonb, 1, '0.25 times 200 = 50.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (14, 'English', 'Production rose from 120 to 150 units. The percent increase is:', '["20%","25%","30%","80%"]'::jsonb, 1, '(30/120)*100% = 25%.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (14, 'English', 'Region X has population 2M and cases 400; Region Y has 1M and cases 300. Higher cases per million?', '["Region X","Region Y","Equal","Cannot tell"]'::jsonb, 1, 'X: 200 per M; Y: 300 per M so Y is higher.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (14, 'English', 'Median of 3, 9, 5, 7, 11 is:', '["3","7","9","11"]'::jsonb, 1, 'Ordered 3,5,7,9,11; median 7.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (14, 'English', 'A bar shows Q1=10, Q2=15, Q3=15, Q4=20. Best description:', '["Steady decline all year","Rise then plateau then rise","All quarters equal","Only Q1 nonzero"]'::jsonb, 1, '10 to 15 rise; 15 plateau; 15 to 20 rise.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (14, 'English', 'If 3 out of 12 audited files had errors, the error rate is:', '["12%","20%","25%","30%"]'::jsonb, 2, '3/12 = 25%.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (14, 'English', 'A line graph of wait time falls each month for six months. The trend is:', '["Increasing","Decreasing","Cyclical with peaks every month","Undefined"]'::jsonb, 1, 'Consistently falling values indicate a decreasing trend.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (14, 'English', 'Dual bar chart: male 40, female 60 in Unit 1. Female percentage in Unit 1 is:', '["40%","50%","60%","100%"]'::jsonb, 2, '60/(40+60)=60%.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (15, 'English', 'What is 18% of 450?', '["72","81","90","98"]'::jsonb, 1, '0.18 times 450 = 81.', 'active', 1, NOW(), NOW());
