INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (15, 'English', 'Compute 125 times 0.8', '["90","100","110","120"]'::jsonb, 1, '125 times 0.8 = 100.', 'active', 1, NOW(), NOW());
