INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (15, 'English', 'Round 3,847 to the nearest hundred:', '["3,800","3,850","3,900","4,000"]'::jsonb, 0, 'Nearest hundred for 3,847 is 3,800.', 'active', 1, NOW(), NOW());
