INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (15, 'English', 'Convert 0.125 to a fraction in lowest terms:', '["1/5","1/8","1/4","3/25"]'::jsonb, 1, '0.125 = 1/8.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (15, 'English', 'If a price increases from 200 pesos to 260 pesos, the percent increase is:', '["25%","30%","60%","130%"]'::jsonb, 1, '60/200 = 30%.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (15, 'English', 'Evaluate: 15 - 3 times 4 + 6', '["9","18","54","6"]'::jsonb, 0, 'Multiplication first: 15 - 12 + 6 = 9.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (15, 'English', 'A ratio of 3:5 equals which fraction for the first part over total?', '["3/5","3/8","5/3","5/8"]'::jsonb, 1, 'First/total = 3/8.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (15, 'English', 'What is 2.5% of 800?', '["15","20","25","40"]'::jsonb, 1, '0.025 times 800 = 20.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (16, 'English', 'Find the next number: 4, 9, 16, 25, _____', '["30","36","49","32"]'::jsonb, 1, 'Squares: next is 36.', 'active', 1, NOW(), NOW());
