INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (16, 'English', 'Find the next: 81, 27, 9, 3, _____', '["1","0","2","6"]'::jsonb, 0, 'Divide by 3 each time: 1.', 'active', 1, NOW(), NOW());
