INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (16, 'English', 'Find the next: 7, 14, 28, 56, _____', '["84","98","112","120"]'::jsonb, 2, 'Doubling: 112.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (16, 'English', 'Find the next: 3, 7, 15, 31, _____', '["47","63","62","55"]'::jsonb, 1, 'Pattern times 2 plus 1: 63.', 'active', 1, NOW(), NOW());
