INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (16, 'English', 'Find the next: 1, 4, 9, 16, 25, _____', '["30","36","49","35"]'::jsonb, 1, 'Perfect squares: 36.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (16, 'English', 'Find the next: 2, 3, 5, 8, 12, _____', '["15","17","18","20"]'::jsonb, 1, 'Differences +1,+2,+3,+4,+5 yielding 17.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (16, 'English', 'Find the next: 64, 32, 16, 8, _____', '["2","4","6","1"]'::jsonb, 1, 'Halving: 4.', 'active', 1, NOW(), NOW());
