INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (1, 'English', 'The President may grant reprieves, commutations, and pardons, except in cases of:', '["All criminal offenses without limit","Impeachment","Traffic violations only","Tax evasion exclusively"]'::jsonb, 1, 'Pardon power generally excludes impeachment cases.', 'active', 1, NOW(), NOW());
