INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (6, 'English', 'Employees were asked to _____ from making public comments on the pending case.', '["refrain","insist","amplify","broadcast"]'::jsonb, 0, 'Refrain from = hold back from doing.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (7, 'English', 'Identify the sentence with an error in article usage.', '["She is an honest official.","He is a university scholar.","They visited an European museum exhibit.","It was an honor to serve."]'::jsonb, 2, 'European begins with a consonant sound /j/; use "a European."', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (7, 'English', 'Which sentence has a tense error?', '["By tomorrow, we will have finished the audit.","Yesterday she submit the forms.","They have worked here since 2019.","He is preparing the slides now."]'::jsonb, 1, 'Past: "submitted," not "submit."', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (7, 'English', 'Choose the sentence with a preposition error.', '["She is good at analysis.","Discuss about the agenda thoroughly is required. (as written)","He arrived at the office early.","They depend on accurate data."]'::jsonb, 1, '"Discuss" does not take "about" — "Discuss the agenda..."', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (8, 'English', 'Which option correctly combines clauses without a comma splice?', '["The forms arrived, they were incomplete.","The forms arrived; they were incomplete.","The forms arrived they were incomplete.","The forms arrived, and incomplete."]'::jsonb, 1, 'A semicolon (or period/conjunction) correctly joins related independent clauses.', 'active', 1, NOW(), NOW());
