INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (10, 'English', 'Passage: "Citizen charters publish service standards and timeframes." A reader can infer agencies aim to:', '["Hide performance expectations","Make service expectations clearer to the public","Abolish all services","Replace laws with posters"]'::jsonb, 1, 'Publishing standards increases clarity of what citizens can expect.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (10, 'English', 'Passage: "When instructions are ambiguous, error rates rise." The implied relationship is:', '["Ambiguity → higher errors","Errors → clearer instructions always","No relationship","Ambiguity reduces errors"]'::jsonb, 0, 'Ambiguous instructions are linked to higher error rates.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (11, 'English', 'Key is to Lock as Password is to:', '["Account access control","Keyboard only","Monitor","Mouse pad"]'::jsonb, 0, 'A key opens/secures a lock; a password controls account access.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (11, 'English', 'Seed is to Tree as Foundation is to:', '["Building","Roof tile only","Window","Paint"]'::jsonb, 0, 'A seed grows into a tree; a foundation underlies a building.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (11, 'English', 'Scalpel is to Surgeon as Trowel is to:', '["Mason / bricklayer","Pilot","Accountant","Pharmacist"]'::jsonb, 0, 'A scalpel is a surgeon''s tool; a trowel is a mason''s tool.', 'active', 1, NOW(), NOW());
