INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (12, 'English', 'If Monday is coded as 123455, and letters map to positions in "MONDAY" uniquely, which statement is safest?', '["Codes must be analyzed with a known mapping key","Any code equals any word","Codes never use digits","Monday has 8 letters"]'::jsonb, 0, 'Without a defined mapping, decode carefully from the given key.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (12, 'English', 'Odd one out: Triangle, Square, Pentagon, Circle', '["Triangle","Square","Pentagon","Circle"]'::jsonb, 3, 'Circle has no straight sides; others are polygons.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (12, 'English', 'If P means +, Q means ×, then 6 P 2 Q 3 =', '["12","18","24","36"]'::jsonb, 0, '6 + 2 × 3 = 6 + 6 = 12 (× before +).', 'active', 1, NOW(), NOW());
