INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (13, 'English', 'Policy memo: "Ban plastic bags to cut marine litter." A critical question is:', '["Whether bag bans reduce marine litter in context","The color of bags only","Whether paper exists","Font choice"]'::jsonb, 0, 'Causal effectiveness of the ban is central.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (13, 'English', 'Which is the best counterexample to "All government websites are always online"?', '["A documented outage of a government site","A private blog offline","A newspaper article on gardening","A working private shop site"]'::jsonb, 0, 'One government site outage falsifies "always online."', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (13, 'English', 'Circular reasoning occurs when:', '["Evidence is independent of the claim","The claim is restated as its own support","Data are tabulated","Samples are large"]'::jsonb, 1, 'Circularity uses the conclusion as a premise.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (14, 'English', 'Enrollment: Year1=200, Year2=250. Absolute increase is:', '["25","50","450","20%"]'::jsonb, 1, '250−200=50 (absolute).', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (14, 'English', 'If Category A is twice Category B and together they total 90, A equals:', '["30","45","60","90"]'::jsonb, 2, '2x + x = 90 → x=30 → A=60.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (14, 'English', 'A stacked bar totals 100%. Segment heights 20, 30, 50 represent:', '["Equal shares","20%, 30%, 50% shares","Only raw counts without percent","Errors always"]'::jsonb, 1, 'On a 100% stacked bar, heights are percentage shares.', 'active', 1, NOW(), NOW());
