INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (15, 'English', 'A number increased by 20% becomes 180. The original number is:', '["144","150","160","216"]'::jsonb, 1, '1.2x=180 → x=150.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (16, 'English', 'Find the next: 10, 11, 13, 16, 20, _____', '["24","25","26","30"]'::jsonb, 1, 'Differences +1,+2,+3,+4,+5 → 20+5=25.', 'active', 1, NOW(), NOW());
