INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (17, 'English', 'A laptop priced ₱30,000 has 12% VAT included. VAT amount is approximately:', '["₱3,214","₱3,600","₱2,800","₱4,000"]'::jsonb, 0, 'Price = base×1.12 → base=30000/1.12≈26786; VAT≈3214.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (17, 'English', 'Walking 4 km/h, time to walk 10 km is:', '["2 hours","2.5 hours","3 hours","4 hours"]'::jsonb, 1, '10/4=2.5 hours.', 'active', 1, NOW(), NOW());
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) VALUES (17, 'English', 'Mixture: 2 liters of 10% solution + 3 liters of 20% solution. Resulting concentration:', '["14%","15%","16%","18%"]'::jsonb, 2, 'Solute: 0.2+0.6=0.8 L in 5 L → 16%.', 'active', 1, NOW(), NOW());
